// ══════════════════════════════════════════════════════════
// STATE MACHINE — Pure JS, zero AI tokens, handles any load
// Groq is only called ONCE per user (final plan generation)
// ══════════════════════════════════════════════════════════

var input   = $input.first().json;
var body    = (input.body !== undefined) ? input.body : input;
var message = (body.message  || '').trim();
var uid     = body.uid       || '';
var idToken = body.idToken   || '';
var inState = body.pbState   || body.state || {};
var step    = inState.step   || 'start';
var data    = inState.data   || {};

// ── Goal classifier (keyword, no AI needed) ─────────────
function classify(t) {
  t = (t || '').toLowerCase();
  if (/weight|fat|slim|lose|lean|cut/.test(t))                 return 'weight_loss';
  if (/muscle|gym|bulk|gains|strength|lift/.test(t))           return 'muscle_gain';
  if (/disciplin|habit|routine|focus|productiv|mindset/.test(t)) return 'discipline';
  if (/financ|money|wealth|invest|budget|debt|income/.test(t)) return 'finance';
  if (/business|startup|brand|client|freelanc|sell|entrepren/.test(t)) return 'business';
  if (/confiden|speak|social|anxiety|shy|assertiv|presenc/.test(t)) return 'confidence';
  if (/relation|love|partner|communicat|friend|network/.test(t)) return 'relationships';
  if (/faith|god|spirit|purpose|pray|meaning|calling/.test(t)) return 'faith';
  if (/ebook|book|write|publish|author|content|blog/.test(t))  return 'ebooks';
  if (/\bai\b|automat|chatgpt|prompt|tech tool/.test(t))       return 'ai_tools';
  if (/health|sleep|nutrition|diet|stress|energy|recover/.test(t)) return 'health';
  return 'general';
}

// ── Button chip sets ───────────────────────────────────
var EXP_CHIPS = [
  'Just starting out',
  'Tried before, struggled',
  'Some good habits already',
  'Consistent — want to level up'
];

var TIME_CHIPS = [
  '30 days — quick wins',
  '60 days — solid progress',
  '90 days — full transformation',
  '6 months — deep change'
];

// Specific follow-up question per goal type
var SPECIFIC_Q = {
  weight_loss:   "What's been your biggest blocker — food choices, consistency, or motivation?",
  muscle_gain:   "Are you currently training, or starting from scratch?",
  discipline:    "What time do you wake up, and what happens in the first 30 minutes of your day?",
  finance:       "Right now, what's costing you the most — overspending, low income, or existing debt?",
  business:      "Do you have an offer or idea already, or are you still figuring out what to sell?",
  confidence:    "What one specific situation makes you feel most held back right now?",
  relationships: "What area needs the most work — communication, meeting people, or existing bonds?",
  faith:         "What does your daily spiritual practice look like right now — if anything?",
  ebooks:        "Do you already have a topic in mind, or are you still searching?",
  ai_tools:      "What task in your work or life do you most want AI to handle?",
  health:        "What's the one health habit you know needs fixing first?",
  general:       "What result in 90 days would make you say — that completely changed my life?"
};

// Empire pillar knowledge — compact, info-dense (used in Groq prompt)
var PILLAR = {
  weight_loss:   'Sleep 7-9h, Protein 0.8-1g/lb bodyweight, 300-500 cal deficit, HIIT 3x/week, strength 2x/week, meal prep Sunday, cut liquid calories, walk 8K steps daily',
  muscle_gain:   'Push-Pull-Legs split 4-5x/week, progressive overload weekly, protein 1g/lb, 250 cal surplus, deload every 6-8 weeks, sleep 8h for muscle synthesis',
  discipline:    'Fixed wake time daily, make bed immediately, no phone first 60min, 90min deep work blocks, one hard thing done before 10am, evening preview of tomorrow, same bedtime',
  finance:       'Track every dollar for 14 days, automate savings on payday, kill highest-interest debt first, emergency fund $1K then $5K, open Roth IRA, index funds $25+ per month',
  business:      'Validate before building, talk to 10 potential customers first, solve 1 specific painful problem, price for value not time, document every process from day 1, recurring revenue over one-time',
  confidence:    'Power posture 2min before high-stakes moments, take action before feeling ready, do one uncomfortable thing daily, reject need for approval, competence compounds confidence',
  relationships: 'Listen to understand not to reply, express specific appreciation daily, communicate needs clearly before they become resentment, lead with value before asking anything, be the same person in every room',
  faith:         '10min morning stillness, write 3 specific gratitudes daily, serve one person weekly, protect time for reflection, define your purpose statement and reread it monthly',
  ebooks:        'One specific problem for one specific reader, 8 chapter questions = your outline, write 500 words daily no editing, publish on KDP free, price $4.99-9.99, get 10 reviews first',
  ai_tools:      'Role + Context + Task + Format = powerful prompts, build one repeatable AI workflow per week, AI drafts you refine, your expertise plus AI speed = your advantage',
  health:        'Same sleep and wake time daily, 2L water before noon, 20min walk after meals, protein at every meal, phone off 90min before bed, track energy hourly for one week',
  general:       'Lock morning routine first, track money weekly, move body daily, one hard task done before 10am, journal 5min nightly, protect 90min of deep work'
};

// ── Step machine ────────────────────────────────────────
var reply    = '';
var buttons  = [];
var callGroq = false;
var groqInput = null;
var nextStep = step;

if (step === 'start') {
  var gt = classify(message);
  data.goalType = gt;
  data.firstMsg = message;
  nextStep = 'experience';
  reply   = "I see you — building something real around **" + gt.replace(/_/g, ' ') + "**.\n\nFirst, where are you starting from right now?";
  buttons = EXP_CHIPS;

} else if (step === 'experience') {
  data.experience = message;
  nextStep = 'timeline';
  reply   = "Got it. How long are you committing to this plan?";
  buttons = TIME_CHIPS;

} else if (step === 'timeline') {
  data.timeline = message;
  nextStep = 'specific';
  reply   = SPECIFIC_Q[data.goalType] || SPECIFIC_Q.general;
  buttons = [];

} else if (step === 'specific') {
  data.specific = message;
  nextStep  = 'done';
  callGroq  = true;
  groqInput = {
    goalType:  data.goalType,
    pillar:    PILLAR[data.goalType] || PILLAR.general,
    experience: data.experience,
    timeline:  data.timeline,
    specific:  data.specific,
    firstMsg:  data.firstMsg
  };

} else if (step === 'done') {
  // User clicked Adjust Plan or Restart
  var lower = message.toLowerCase();
  if (lower.indexOf('restart') !== -1) {
    nextStep = 'start';
    data     = {};
    reply    = "Let\'s start fresh. What are you here to build?";
    buttons  = ['Finance', 'Fitness', 'Discipline', 'Business', 'Confidence', 'Faith'];
  } else {
    // Adjust — let Groq refine with the new message
    data.adjustRequest = message;
    nextStep  = 'done';
    callGroq  = true;
    groqInput = {
      goalType:  data.goalType,
      pillar:    PILLAR[data.goalType] || PILLAR.general,
      experience: data.experience,
      timeline:  data.timeline,
      specific:  data.specific,
      firstMsg:  data.firstMsg,
      adjustRequest: message
    };
  }

} else {
  nextStep = 'start';
  reply    = "Let\'s start fresh. What are you here to build?";
  buttons  = ['Finance', 'Fitness', 'Discipline', 'Business', 'Confidence', 'Faith'];
}

return [{
  json: {
    callGroq:  callGroq,
    groqInput: groqInput,
    reply:     reply,
    buttons:   buttons,
    state:     { step: nextStep, data: data },
    uid:       uid,
    plan:      null,
    completed: false
  }
}];

// Build Groq request — only runs for final plan generation
// Keeps system prompt SHORT to save tokens (~280 tokens)
var sm = $input.first().json;
var g  = sm.groqInput;

var adjustNote = g.adjustRequest
  ? '\n\nUSER ADJUSTMENT REQUEST: ' + g.adjustRequest + '\nRevise the plan to address this specifically.'
  : '';

var SYSTEM = 'You are the Empire AI Coach — direct, specific, no fluff. You sound like a high-level mentor who has personally done this. Never give generic advice. Every line is specific to this exact person.\n\nOUTPUT RULES:\n- Bold headers, dash bullets\n- Specific numbers always (times, amounts, percentages, reps, dollars)\n- Reference their exact situation in the first sentence\n- Max 420 words in the plan\n- End buttons are always: ["Execute Plan","Adjust Plan","Restart"]\n\nReturn ONLY valid JSON:\n{"reply":"full plan in markdown","buttons":["Execute Plan","Adjust Plan","Restart"],"plan_ready":true,"plan":{"mainGoal":"","goalType":"","category":"","goals":[],"builtAt":""}}';

var USER_MSG = 'Build a personalized ' + g.timeline + ' Empire Plan.\n\nGoal: ' + (g.goalType || '').replace(/_/g,' ') + '\nExperience level: ' + g.experience + '\nTimeline: ' + g.timeline + '\nTheir situation: ' + g.specific + '\nFirst message: ' + g.firstMsg + '\n\nApply this domain knowledge precisely:\n' + g.pillar + adjustNote;

return [{
  json: {
    model: 'llama-3.3-70b-versatile',
    messages: [
      { role: 'system', content: SYSTEM },
      { role: 'user',   content: USER_MSG }
    ],
    temperature: 0.82,
    max_tokens: 950,
    response_format: { type: 'json_object' }
  }
}];

// Parse Groq response and build final dashboard payload
var groq = $input.first().json;
var sm   = $('State Machine').first().json;

// Extract text from Groq response
var text = '';
try { text = groq.choices[0].message.content; } catch(e) {}

// Parse JSON (with fallback for edge cases)
var parsed = {};
try {
  parsed = JSON.parse(text);
} catch(e) {
  // Try to pull JSON out if Groq wrapped it in markdown
  var m = (text || '').match(/```json([\s\S]*?)```/) || (text || '').match(/({[\s\S]*})/);
  if (m) { try { parsed = JSON.parse(m[1] || m[0]); } catch(e2) {} }
}

// Fallback if parsing fully fails
if (!parsed.reply) {
  parsed.reply    = 'Your Empire Plan is ready. Hit Execute Plan to lock it in and start building.';
  parsed.buttons  = ['Execute Plan', 'Adjust Plan', 'Restart'];
  parsed.plan_ready = true;
}

// Stamp plan with timestamp
var plan = parsed.plan || null;
if (plan) {
  plan.builtAt = plan.builtAt || new Date().toISOString();
  if (!plan.goalType && sm.groqInput) plan.goalType = sm.groqInput.goalType || '';
  if (!plan.category && plan.goalType) plan.category = plan.goalType;
}

return [{
  json: {
    reply:     parsed.reply,
    buttons:   parsed.buttons   || ['Execute Plan', 'Adjust Plan', 'Restart'],
    state:     sm.state,
    plan:      plan,
    completed: true
  }
}];
